import React from 'react';
import { LucideIcon } from 'lucide-react';

interface SectionCardProps {
  title: string;
  items: string[];
  icon: LucideIcon;
  variant: 'default' | 'danger' | 'warning' | 'success';
  className?: string;
}

export const SectionCard: React.FC<SectionCardProps> = ({ title, items, icon: Icon, variant, className = '' }) => {
  const getColors = () => {
    switch (variant) {
      case 'danger': return 'bg-red-50 border-red-100 text-red-900 icon-red-600';
      case 'warning': return 'bg-orange-50 border-orange-100 text-orange-900 icon-orange-600';
      case 'success': return 'bg-emerald-50 border-emerald-100 text-emerald-900 icon-emerald-600';
      default: return 'bg-white border-slate-100 text-slate-800 icon-blue-600';
    }
  };

  const colors = getColors();
  const iconColor = colors.split(' ').find(c => c.startsWith('icon-'))?.replace('icon-', 'text-') || 'text-slate-600';

  return (
    <div className={`p-6 rounded-2xl border ${colors.split(' ').slice(0, 2).join(' ')} shadow-sm h-full ${className}`}>
      <div className="flex items-center gap-3 mb-4">
        <div className={`p-2 rounded-lg bg-white/60 ${iconColor}`}>
          <Icon className="w-6 h-6" />
        </div>
        <h3 className={`text-lg font-bold ${colors.split(' ')[2]}`}>{title}</h3>
      </div>
      <ul className="space-y-3">
        {items.length > 0 ? (
          items.map((item, idx) => (
            <li key={idx} className="flex items-start gap-2.5 text-slate-700">
              <span className={`mt-2 w-1.5 h-1.5 rounded-full flex-shrink-0 ${iconColor.replace('text', 'bg')}`} />
              <span className="leading-relaxed">{item}</span>
            </li>
          ))
        ) : (
          <li className="text-slate-400 italic text-sm">Aucune donnée spécifique listée.</li>
        )}
      </ul>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Search, Loader2 } from 'lucide-react';

interface SearchBarProps {
  onSearch: (query: string) => void;
  isLoading: boolean;
  externalQuery?: string;
}

export const SearchBar: React.FC<SearchBarProps> = ({ onSearch, isLoading, externalQuery }) => {
  const [input, setInput] = useState('');

  // Met à jour le champ texte si la recherche change depuis l'extérieur (ex: clic sur une alternative)
  useEffect(() => {
    if (externalQuery) {
      setInput(externalQuery);
    }
  }, [externalQuery]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim()) {
      onSearch(input.trim());
    }
  };

  return (
    <form onSubmit={handleSubmit} className="w-full relative group">
      <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none">
        {isLoading ? (
          <Loader2 className="h-5 w-5 text-blue-500 animate-spin" />
        ) : (
          <Search className="h-5 w-5 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
        )}
      </div>
      <input
        type="text"
        className="block w-full pl-10 pr-20 py-3.5 bg-white border border-slate-200 rounded-xl text-slate-900 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 shadow-sm transition-all duration-300 text-base"
        placeholder="Rechercher (ex: Doliprane)"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        disabled={isLoading}
      />
      <button
        type="submit"
        disabled={isLoading || !input.trim()}
        className="absolute right-1.5 top-1.5 bottom-1.5 px-3 bg-blue-600 text-white rounded-lg font-medium text-sm hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95 shadow-md hover:shadow-lg"
      >
        Go
      </button>
    </form>
  );
};

import React, { useState } from 'react';
