    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const handleAlternativeClick = (name: string) => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    handleSearch(name);
  };

  return (
    // Outer Wrapper - Background for Desktop
    <div className="min-h-screen bg-slate-900 md:bg-slate-200 flex justify-center items-start pt-0 md:py-8 font-sans text-slate-900">

      {/* Mobile Device Container */}
      <div className="w-full max-w-[480px] bg-slate-50 min-h-screen md:min-h-[850px] md:h-auto md:rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden relative border-x border-slate-200 transition-all duration-300">

        {/* Header */}
        <header className="bg-white border-b border-slate-100 sticky top-0 z-50 transition-transform duration-300">
          <div className="px-5 h-16 flex items-center justify-between">
            <div className="flex items-center gap-2.5 cursor-pointer active:scale-95 transition-transform" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>
