                <Stethoscope className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-lg font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-700 to-cyan-600 tracking-tight">
                PharmaGuide
              </h1>
            </div>
            {/* Mobile simplified nav */}
            <button onClick={() => scrollToSection('help')} className="p-2 text-slate-400 hover:text-blue-600 transition-colors active:scale-90">
              <HelpCircle className="w-6 h-6" />
            </button>
          </div>
        </header>

        <main className="flex-grow w-full px-5 py-6 overflow-y-auto scroll-smooth">
          {/* Search Hero */}
          <div className={`transition-all duration-500 ease-in-out transform ${state.data ? 'mb-6 translate-y-0' : 'mb-8 mt-4 text-center translate-y-0'}`}>
            {!state.data && (
              <div className="animate-fade-in-up">
                <h2 className="text-2xl font-extrabold text-slate-900 mb-3 tracking-tight">
