                  <span className="text-blue-600">que recherchez-vous ?</span>
                </h2>
                <p className="text-sm text-slate-500 mb-8 mx-auto leading-relaxed">
                  Accédez instantanément aux notices simplifiées de vos médicaments grâce à l'IA.
                </p>
              </div>
            )}
            <SearchBar onSearch={handleSearch} isLoading={state.loading} externalQuery={state.query} />
          </div>

          {/* Error State */}
          {state.error && (
            <div className="p-4 bg-red-50 border border-red-100 rounded-2xl text-red-700 text-sm flex items-center gap-3 animate-fade-in mb-6 shadow-sm">
              <AlertTriangle className="w-5 h-5 flex-shrink-0" />
