  const [state, setState] = useState<SearchState>({
    query: '',
    loading: false,
    error: null,
    data: null,
  });

  const [patientMedications, setPatientMedications] = useState<MedicationInfo[]>([]);

  // Charger la liste du patient au démarrage
  useEffect(() => {
    const saved = localStorage.getItem('pharmaguide_list');
    if (saved) {
      try {
        setPatientMedications(JSON.parse(saved));
      } catch (e) {
        console.error("Erreur de lecture du stockage local");
      }
    }
  }, []);

  // Sauvegarder la liste quand elle change
  useEffect(() => {
    localStorage.setItem('pharmaguide_list', JSON.stringify(patientMedications));
  }, [patientMedications]);

  const handleSearch = async (query: string) => {
    setState(prev => ({ ...prev, query, loading: true, error: null, data: null }));
    try {
      const result = await fetchMedicationInfo(query);
      setState(prev => ({ ...prev, loading: false, data: result }));
    } catch (err) {
      setState(prev => ({ 
        ...prev, 
        loading: false, 
        error: "Impossible de récupérer les informations. Vérifiez votre connexion." 
      }));
    }
