                {patientMedications.map((med, idx) => (
                  <div 
                    key={idx}
                    onClick={() => selectFromList(med)}
                    className="flex-shrink-0 flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 rounded-xl shadow-sm hover:border-blue-400 cursor-pointer active:scale-95 transition-all group"
                  >
                    <div className={`w-2 h-2 rounded-full ${med.warningLevel === 'high' ? 'bg-red-500' : med.warningLevel === 'medium' ? 'bg-orange-500' : 'bg-emerald-500'}`} />
                    <span className="text-sm font-semibold text-slate-700 truncate max-w-[100px]">{med.name}</span>
                    <button 
