                    <span className="font-medium">{state.data.usageTips}</span>
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <SectionCard title="Indications" items={state.data.indications} icon={Pill} variant="default" className="animate-fade-in-up delay-100" />
